func validateFilePathPATH_ABSOLUTE(path string) error {
	if !filepath.IsAbs(path) {
		return protoerrors.NewErrMissingInvalidData(nil, "path must be absolute, got: %s", path)
	}
	return nil
}
func validateFilePathPATH_RELATIVE(path string) error {
	if filepath.IsAbs(path) {
		return protoerrors.NewErrMissingInvalidData(nil, "path must be relative, got: %s", path)
	}
	return nil
}
func validateFilePathPATH_ANY(path string) error {
	// Any path is valid as long as it's not empty
	if path == "" {
		return protoerrors.NewErrMissingInvalidData(nil, "path cannot be empty")
	}
	return nil
}

func validateFilePathPATH_DIR(path string) error {
	// Directory path — must not be empty
	if path == "" {
		return protoerrors.NewErrMissingInvalidData(nil, "directory path cannot be empty")
	}
	return nil
}

var validateFilePath4 = validateFilePathPATH_DIR

